from collections import deque


def reachable(n, start_a):
    """Return (A count, single move used) states reachable at most once."""
    if n < 0 or not 0 <= start_a <= n:
        raise ValueError("Invalid total or starting count")

    start = (start_a, False)
    seen = {start}
    queue = deque([start])

    while queue:
        a, used = queue.popleft()
        b = n - a
        next_states = []

        if a >= 2:
            next_states.append((a - 2, used))
        if b >= 2:
            next_states.append((a + 2, used))
        if not used:
            if a >= 1:
                next_states.append((a - 1, True))
            if b >= 1:
                next_states.append((a + 1, True))

        for state in next_states:
            if state not in seen:
                seen.add(state)
                queue.append(state)

    return seen


def check():
    for n in range(21):
        for start_a in range(n + 1):
            states = reachable(n, start_a)
            original = {a for a, used in states if not used}
            at_most_once = {a for a, _ in states}
            exactly_once = {a for a, used in states if used}

            assert original == {
                t for t in range(n + 1) if (t - start_a) % 2 == 0
            }
            assert at_most_once == set(range(n + 1))
            assert exactly_once == {
                t for t in range(n + 1)
                if n > 0 and (t - start_a) % 2 != 0
            }

    print("All reachability characterizations hold for N = 0..20.")


if __name__ == "__main__":
    check()
```

