    except TypeError as exc:
        raise ValueError('groups must be iterable') from exc

    validated = []
    for group in iterator:
        if not isinstance(group, (tuple, list)) or len(group) != 2:
            raise ValueError('each group must be a character/count pair')
        ch, count = group
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError('character must be one Unicode code point')
        if isinstance(count, bool) or not isinstance(count, int) or count <= 0:
            raise ValueError('count must be a positive integer')
        validated.append((ch, count))

    if offset > sum(count for _, count in validated):
        raise ValueError('offset is outside the encoding')

